1	// Scope-blind mechanism (no policy, no scope knowledge): given a built context
2	// and the discovered packs, run the ACTIVE packs' rules that a caller-supplied
3	// predicate admits, and return their findings. The world and work runners each
4	// call this with their own `includeRule` — this file never names a scope, so
5	// the two runners stay independent of each other while sharing the walk.
6	import { runRule } from './helpers/work.mjs';
7	import { isActive } from '../pack_loader/pack-registry.mjs';
8	
9	// A pack's contributedRules seam: the pack interprets the contributions other
10	// packs address to it on their manifests (`contributes`), returning first-class
11	// rules — how packs compose through declaration + configuration instead of
12	// importing each other's code. Isolated per pack, like manifest loading: one
13	// broken seam (a consumer-authored local pack's, say) must not sink the run.
14	// `onError` lets a caller turn a broken seam into a finding; passing none
15	// swallows it (a runner that doesn't own config diagnostics stays quiet).
16	export function contributedRules(pack, fromPacks, onError = null) {
17	  try { return pack.contributedRules?.(fromPacks) ?? []; }
18	  catch (e) { onError?.(e); return []; }
19	}
20	
21	// The full rule catalog the given packs carry, id-sorted: a pack's own rules,
22	// the checks its bundled skills own, and the rules built from contributions
23	// addressed to it. The ONE place the three sources are summed — `--list`
24	// prints it and the catalog's own tally guard counts it, so neither can
25	// disagree with the runner about what rules exist, and a fourth source added
26	// later lands in both for free.
27	export function packRules(packs) {
28	  return [
29	    ...packs.flatMap((p) => p.rules ?? []),
30	    ...packs.flatMap((p) => p.skillChecks ?? []),
31	    ...packs.flatMap((p) => contributedRules(p, packs)),
32	  ].sort((a, b) => a.id.localeCompare(b.id));
33	}
34	
35	// Every finding from the active packs' rules that `includeRule` admits. A rule
36	// turned `off` in settings is skipped. `onContributeError(pack, err)` is invoked
37	// when a pack's contributedRules seam throws (the caller decides whether that
38	// becomes a finding).
39	export function runActivePackRules(ctx, packs, { includeRule, onContributeError = null }) {
40	  const findings = [];
41	  // Expose the discovered packs to any rule that reasons about pack metadata
42	  // (e.g. the adoption-interview hygiene check reads each active pack's declared
43	  // questions) — checks run synchronously and can't re-discover packs themselves.
44	  ctx.packs = packs;
45	  const activePacks = packs.filter((p) => isActive(p, ctx.config));
46	  for (const pack of activePacks) {
47	    const contributed = contributedRules(pack, activePacks,
48	      onContributeError ? (e) => onContributeError(pack, e) : null);
49	    for (const rule of [...(pack.rules ?? []), ...(pack.skillChecks ?? []), ...contributed]) {
50	      if (!includeRule(rule)) continue;
51	      if (ctx.config.rules[rule.id] === 'off') continue;
52	      findings.push(...runRule(rule, ctx));
53	    }
54	  }
55	  return findings;
56	}
57

