1	// THE PACK MANIFEST SPEC — the single declarative statement of what a
2	// `pack.mjs` may and must carry. Everything a pack declares about itself is
3	// described here once, and `validateManifest` is the only thing that judges a
4	// manifest against it. The loader calls it on every pack it imports (canon and a
5	// consumer's own `local_packs/` alike), so a malformed or incomplete manifest
6	// surfaces as a blocking `config` error at load — the same class as invalid JSON
7	// in `.claudinite-settings.json`.
8	//
9	// WHY A SPEC AND NOT A CHECK. A required manifest field is part of the pack
10	// contract, not a conformance opinion about a repo's content: a conformance rule
11	// would have to be declared BY a pack, run only when that pack is active, and
12	// re-derive the manifest by reading its source text — enforcing the shape of the
13	// system from inside one of its members. The spec is upstream of every pack, so
14	// there is nothing to declare and nothing to parse.
15	//
16	// No filesystem, and its one import is the engine's own pure version module: the
17	// caller supplies the facts from disk (the `skills/` directory listing), so this
18	// module is pure and testable standalone. Its other half is
19	// `pack-conventions.mjs`, which reads the pack directory and fills in what the
20	// tree already says — so by the time a manifest reaches this spec, `id`, `prose`,
21	// `badge` and `skills` are present whether or not the author wrote them.
22	import { isDeclaredVersion } from '../version.mjs';
23	
24	// The routing budget. Both sides of `ruleRoutingGuidance` become one row of the
25	// pack catalog (packs/directory.GENERATED.md), which a session reads when deciding
26	// which pack owns a piece of content — so the cap keeps a row scannable: enough for
27	// a boundary and a pointer to the pack that owns the other side.
28	export const MAX_ROUTING_WORDS = 20;
29	
30	// The two conformance scopes. A rule's scope is its PLACEMENT on the manifest —
31	// `worldRules` audit repo state, `workRules` judge the change and session in
32	// front of you — so the two runners' partition is declared where a reader of the
33	// pack can see it, and a rule module never restates (or contradicts) it.
34	export const RULE_SCOPES = { worldRules: 'world', workRules: 'work' };
35	
36	const isPlainObject = (v) => v !== null && typeof v === 'object' && !Array.isArray(v);
37	const isStringArray = (v) => Array.isArray(v) && v.every((x) => typeof x === 'string');
38	const isRuleArray = (v) => Array.isArray(v) && v.every((x) => isPlainObject(x) && typeof x.id === 'string' && typeof x.run === 'function');
39	
40	// A version — engine or pack — is date-anchored `<day>.<n>`, or a legacy positive
41	// integer while the tolerance lasts (engine/version.mjs owns both). Shared by
42	// both version fields below, and the only judgment either gets: `minEngineVersion` is
43	// validated for SHAPE here and enforced by the pack updater, which is the only caller
44	// that knows what engine version the target repo actually runs.
45	
46	// A seed op names a template in the pack and where a fresh install puts it. SEEDED,
47	// NOT CONVERGED: the file becomes the repo's from that moment, and no update ever
48	// rewrites it — the README pack-badge row is the precedent, seeded at adoption
49	// precisely so later runs cannot rewrite a member's README (DESIGN §4).
50	//
51	// The run-once guarantee is STRUCTURAL, not a flag anyone must remember to set: only
52	// the install flow reads this field, so an update has nothing to re-run. That is why
53	// the shape stays this narrow — a general op here would be an update-time hazard
54	// waiting for a caller.
55	const isSeedOps = (v) => Array.isArray(v)
56	  && v.every((o) => o !== null && typeof o === 'object' && typeof o.template === 'string' && typeof o.dest === 'string');
57	
58	// A handover step needs all three parts or it is not one. `step` alone is a note
59	// someone has to interpret; `breaks` is how an adopter judges whether to do it now;
60	// `done` is what lets the tracking issue ever be closed. The shape IS the basics rule
61	// for handing over human-only work, so a pack that declares one declares all of it.
62	const isAdoptionHandover = (v) => Array.isArray(v) && v.every((o) => o !== null
63	  && typeof o === 'object'
64	  && ['step', 'breaks', 'done'].every((k) => typeof o[k] === 'string' && o[k].trim() !== ''));
65	
66	// Every field a manifest may carry. `required` fields must be present; the rest
67	// are validated only when declared. An UNDECLARED field is an error: the spec is
68	// the closed vocabulary of a pack, so a typo (`rule:`, `skill:`) fails loudly
69	// instead of being silently ignored forever.
70	//
71	// The two version fields are OPTIONAL BY CONTRACT, not by leniency: a member's own
72	// `local/packs/` are repo-owned and distributed to nobody, so they carry no version
73	// and no update flow (docs/versioned-updates/DESIGN.md §8). Requiring the field would
74	// invalidate every local pack in the fleet at once, with nothing to carry the fix.
75	// Every CANON pack does declare both — asserted by engine-tests/pack-versions.test.mjs,
76	// which is a canon-side test rather than a conformance rule precisely because it is
77	// true of this tree only.
78	export const PACK_FIELDS = {
79	  id: { required: true, describe: 'the pack id — the directory name by convention, and declared only to override that', valid: (v) => typeof v === 'string' && v.length > 0 },
80	  version: { describe: 'the pack version — date-anchored <day>.<n>, advanced by a pack release', valid: isDeclaredVersion },
81	  minEngineVersion: { describe: 'the lowest engine version this pack version runs on', valid: isDeclaredVersion },
82	  seedOps: { describe: 'files seeded ONCE at install and owned by the repo thereafter, as { template, dest } pairs', valid: isSeedOps },
83	  adoptionHandover: { describe: 'steps only a human can do after adoption, as { step, breaks, done } — printed by the install flow and filed as a tracking issue', valid: isAdoptionHandover },
84	  ruleRoutingGuidance: { required: true, describe: 'what belongs in this pack and what does not, each at most 20 words', valid: isPlainObject },
85	  badge: { describe: 'the pack badge filename, resolved off the pack directory — badge.svg by convention where one is present', valid: (v) => typeof v === 'string' },
86	  hidden: { describe: 'whether the pack is withheld from the adoptable-pack catalog (packs/directory.GENERATED.md) — for a pack that exists to serve the corpus itself rather than to be adopted', valid: (v) => typeof v === 'boolean' },
87	  detect: { describe: 'a fingerprint predicate over the repo context, or null', valid: (v) => v === null || typeof v === 'function' },
88	  marker: { describe: 'a human-readable glob naming what detect looks for, or null', valid: (v) => v === null || typeof v === 'string' },
89	  prose: { describe: 'the filename injected at session start, or null — RULES.md by convention where one is present, so declare it only to name another file or to suppress it', valid: (v) => v === null || typeof v === 'string' },
90	  seededByDefault: { describe: 'whether bootstrap --init seeds this pack everywhere', valid: (v) => typeof v === 'boolean' },
91	  requires: { describe: 'pack ids this pack depends on, resolved when the declaration is written', valid: isStringArray },
92	  contributes: { describe: 'rules addressed to another pack, keyed by that pack id', valid: isPlainObject },
93	  contributedRules: { describe: 'the seam interpreting other packs contributions to this one', valid: (v) => typeof v === 'function' },
94	  env: { describe: 'environment requirements the pack needs to run its checks', valid: isPlainObject },
95	  questions: { describe: 'the pack adoption-interview questions', valid: (v) => Array.isArray(v) },
96	  skills: { describe: 'the skill directory names mounted from this pack skills/ — every subdirectory carrying a SKILL.md by convention, so declare it only to withhold one', valid: isStringArray },
97	  worldRules: { describe: 'rules auditing repo state (check_the_world)', valid: isRuleArray },
98	  workRules: { describe: 'rules judging the current change and session (check_the_work)', valid: isRuleArray },
99	};
100	
101	const REQUIRED = Object.entries(PACK_FIELDS).filter(([, f]) => f.required).map(([k]) => k);
102	
103	const wordCount = (s) => s.trim().split(/\s+/).filter(Boolean).length;
104	
105	// Validate one manifest against the spec. `skillDirs` is the list of directory
106	// names under `<pack>/skills/` (the caller reads it; this module touches no
