1	// Fresh-path wiring convergence (task-code-work DESIGN §7, the primitive absorbed from
2	// #405). The deterministic half of the self-refresh that has nothing to do with the
3	// vendored mount's CONTENT: the repo-specific wiring EVERY Claudinite member carries,
4	// converged idempotently in code so the nightly refresh never needs a model to re-enact
5	// bootstrap's prose.
6	//
7	// DISTRIBUTION WIRING ONLY. What a member needs in order to receive and load pack
8	// content — the settings hooks, the rules index and the CLAUDE.md import that loads it,
9	// the .gitattributes entries, the badge row, the repo's own local pack. Scheduling
10	// wiring is not here: the two workflow files belong to the mechanism that runs them and
11	// are scaffolded at adoption by the tasks pack (#1317), so a member without that pack
12	// converges exactly this and nothing about a queue it does not have.
13	//
14	// One source of truth: bootstrap Part 5 describes this same set for a fresh adoption;
15	// this module is what both bootstrap and the update flows CALL, so the wiring can never
16	// drift between "how a repo is set up" and "how the nightly keeps it set up".
17	//
18	// Operates on a repo working tree at `root` with node:fs directly (like
19	// apply-vendor-set.mjs), returning a summary of what it changed — idempotent: a
20	// repo already converged produces an empty change list.
21	
22	import { existsSync, readFileSync, writeFileSync, mkdirSync } from 'node:fs';
23	import { join, dirname, relative, sep } from 'node:path';
24	import { pathToFileURL } from 'node:url';
25	import { writeRulesIndex, RULES_INDEX_FILE, RULES_INDEX_IMPORT } from './pack_loader/generate-rules-index.mjs';
26	import { LOCAL_PACKS_SUBDIR, LOCAL_DECL_PREFIX, SHARED_SUBDIR } from './pack_loader/pack-registry.mjs';
27	import { settingsPath } from './settings-file.mjs';
28	import { ENDPOINTS_KEY, LEGACY_ENDPOINTS_KEY } from './checks/helpers/repo-context.mjs';
29	
30	// The settings-hook registrations a scheduled repo carries (bootstrap Part 5).
31	// Ensured present without clobbering — a set-union keyed on the command string, so
32	// a repo's own extra hooks and any hand-added entries survive untouched.
33	export const REQUIRED_HOOKS = [
34	  { event: 'SessionStart', matcher: null, command: 'bash $CLAUDE_PROJECT_DIR/.claudinite/shared/engine/hooks/session-start-command.sh' },
35	  { event: 'Stop', matcher: null, command: 'node $CLAUDE_PROJECT_DIR/.claudinite/shared/engine/hooks/stop-command.mjs' },
36	  { event: 'PreToolUse', matcher: 'Bash', command: 'node $CLAUDE_PROJECT_DIR/.claudinite/shared/engine/hooks/pretooluse-command.mjs' },
37	  { event: 'SessionEnd', matcher: null, command: 'node $CLAUDE_PROJECT_DIR/.claudinite/shared/engine/hooks/session-end-command.mjs' },
38	];
39	
40	export const SETTINGS_PATH = '.claude/settings.json';
41	export const CLAUDE_MD = 'CLAUDE.md';
42	export const README = 'README.md';
43	
44	// The pack-badge row: the marks of the packs this repo declares, on a single
45	// line of its README. Adoption seeds it and the repo owns it from there — which
46	// is why the row is gated behind `{ badges: true }` (the CLI's `--badges`, passed
47	// by bootstrap alone) rather than converged like the surfaces around it. A
48	// README belongs to its repo: a nightly that re-derived this row would rewrite a
49	// member's README every time its declaration moved, so the nightly stays out and
50	// a stale row is the repo's to fix (re-run the converge with `--badges`).
51	//
52	// Delimited by HTML comments rather than located by position, so the row can be
53	// re-converged in place wherever the repo has moved it, and so anything the repo
54	// writes AFTER the closing marker on the same line (a tagline, a build badge) is
55	// its own and survives untouched — which is why the CLOSING marker stays inline,
56	// at the end of the badges' own line.
57	//
58	// The OPENING marker gets a line to itself, and that newline is load-bearing: a
59	// line that BEGINS with `<!--` opens a CommonMark HTML block, and every character
60	// through the line carrying `-->` is then emitted as raw HTML. Put the badges
61	// after the opening marker on one line and a README renders the literal text
62	// `![basics](…)` instead of the images (#587). Breaking the line ends the HTML
63	// block at the marker, so the badges start a paragraph and parse as markdown.
64	export const BADGE_ROW_START = '<!-- claudinite:packs -->';
65	export const BADGE_ROW_END = '<!-- /claudinite:packs -->';
66	const BADGE_ROW_RE = new RegExp(`${BADGE_ROW_START}[\\s\\S]*?${BADGE_ROW_END}`);
67	
68	// The retired corpus-index import (#385): a line importing `.claudinite/shared/CLAUDE.md`.
69	// The whole line (and its trailing newline) is removed wherever it appears.
70	const CORPUS_IMPORT_RE = /^.*@\.claudinite\/shared\/CLAUDE\.md.*\n?/m;
71	
72	// The project's settings, loaded through the one reader that validates them.
73	// Dynamic and in one place: the scheduler reaches the checks helpers exactly here,
74	// so the cross-tree import stays a single, reviewable edge.
75	const repoConfig = async (root) => (await import('./checks/helpers/repo-context.mjs')).loadConfig(root);
76	
77	// Re-converge the scheduler workflow to the vendored stub, with the cron minute set
78	// to this repo's stable hashed value (never guessed — hash-minute.mjs, a pure
79	// function of the full name, so re-vendors and this convergence agree) and the
80	// `stubText` is the vendored stub's content (the caller reads it from the mount).
81	// Returns true when the file was written (absent, or drifted from the target).
82	// What this repo's scheduler workflow SHOULD contain — the stub with its cron
83	// resolved, as text, touching no disk.
84	//
85	// A workflow is now a pure function of its stub. Secrets used to be stamped in here
86	// by name, which made these files a function of the TASK SET and is what wedged a
87	// member in #1296. They are stamped by the tasks pack's converge-workflows.mjs, at
88	// the `# claudinite:secrets` marker in its executor stub (#1336).
89	//
90	// Split out from the converge below because the pack update flow needs the answer
91	// without the side effect: it cannot write this file (its caller pushes with the
92	// Action's GITHUB_TOKEN, which GitHub never lets near `.github/workflows/`), so it
93	// WITHHOLDS the content and hands it to a lane that can. A flow that had to write
94	// the file in order to learn what it should say could not do that.
95	// Ensure the required settings hooks are present (add-if-missing, never clobber).
96	// Returns { added: [labels], error? }. A malformed settings file is reported, never
97	// overwritten (the transactional stance — surface it, don't destroy hand config).
98	export function ensureHooks(root) {
99	  const path = join(root, SETTINGS_PATH);
100	  let settings = {};
101	  if (existsSync(path)) {
102	    try { settings = JSON.parse(readFileSync(path, 'utf8')); }
103	    catch { return { added: [], error: `${SETTINGS_PATH} is not valid JSON — left untouched` }; }
104	  }
105	  settings.hooks ??= {};
106	  const added = [];
107	  for (const h of REQUIRED_HOOKS) {
108	    const list = (settings.hooks[h.event] ??= []);
109	    const present = list.some((group) =>
110	      (h.matcher == null || group.matcher === h.matcher)
111	      && (group.hooks ?? []).some((entry) => entry?.command === h.command));
112	    if (!present) {
113	      list.push({ ...(h.matcher != null ? { matcher: h.matcher } : {}), hooks: [{ type: 'command', command: h.command }] });
114	      added.push(`${h.event}${h.matcher ? `[${h.matcher}]` : ''}`);
115	    }
116	  }
117	  if (added.length) {
118	    mkdirSync(dirname(path), { recursive: true });
119	    writeFileSync(path, JSON.stringify(settings, null, 2) + '\n');
120	  }
121	  return { added };
122	}
123	
124	// Remove the retired `@.claudinite/shared/CLAUDE.md` corpus-index import (#385) from
125	// the repo's CLAUDE.md. Returns true when a line was removed.
126	export function removeRetiredCorpusImport(root) {
127	  const path = join(root, CLAUDE_MD);
128	  if (!existsSync(path)) return false;
129	  const text = readFileSync(path, 'utf8');
130	  if (!CORPUS_IMPORT_RE.test(text)) return false;
131	  writeFileSync(path, text.replace(CORPUS_IMPORT_RE, ''));
132	  return true;
133	}
134	
135	// The CLAUDE.md channel (#807): the generated rules index, plus the one line in the
136	// repo's own CLAUDE.md that imports it. Converged here rather than left to a session
137	// because the index is a function of the DECLARATION — so the two flows that already
138	// change a declaration (the nightly engine refresh and any pack change) are exactly
139	// the moments it can go stale, and both call convergeWiring.
140	//
141	// NOT the retired `@.claudinite/shared/CLAUDE.md` this file still strips above. That
142	// import reached INTO the mount, which is one-directional and slated to become a
143	// submodule; this one names a consumer-owned file sitting BESIDE it, derived from the
144	// consumer's own declaration. The two coexist deliberately: a member converging today
145	// loses the old shape and gains the new one in the same pass.
146	//
147	// The import goes after the first `# ` heading when the repo has one (the badge row's
148	// placement rule, for the same reason — a repo's title stays its first line), and at
149	// the very top otherwise. A repo with no CLAUDE.md at all gets one: without it the
150	// index is a file nothing loads.
151	const RULES_INDEX_IMPORT_RE = new RegExp(`^\\s*${RULES_INDEX_IMPORT.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}\\s*$`, 'm');
152	
153	export function ensureRulesIndexImport(root) {
154	  const path = join(root, CLAUDE_MD);
155	  if (!existsSync(path)) {
156	    writeFileSync(path, `${RULES_INDEX_IMPORT}\n`);
157	    return true;
158	  }
159	  const text = readFileSync(path, 'utf8');
160	  if (RULES_INDEX_IMPORT_RE.test(text)) return false;
161	  const lines = text.split('\n');
162	  const title = lines.findIndex((l) => l.startsWith('# '));
163	  const at = title === -1 ? 0 : title + 1;
164	  lines.splice(at, 0, ...(at === 0 ? [RULES_INDEX_IMPORT, ''] : ['', RULES_INDEX_IMPORT]));
165	  writeFileSync(path, lines.join('\n'));
166	  return true;
167	}
168	
169	// A GENERATED file wants a `merge=ours` .gitattributes entry (the canon's
170	// GENERATED-file discipline and the `generated-merge-driver` check that enforces it),
171	// declared in the same converge that first writes the file — otherwise every member
172	// picks up an advisory finding on a file it did not author.
173	export const RULES_INDEX_MERGE_ATTR = 'claudinite-rules.GENERATED.md merge=ours';
174	
175	export function ensureRulesIndexMergeAttribute(root) {
176	  return ensureAttributeLine(root, RULES_INDEX_MERGE_ATTR);
177	}
178	
179	// The shared mount is canon-owned content the member never authored, so the git HOST
180	// is told so: Linguist keeps a member's language stats off the corpus (which outweighs
181	// a small member's own source by byte count) and collapses the mount in a converge
182	// diff. Presentation only — the CHECK-scope exclusion is a separate, structural rule
183	// in the file-set builder (engine/checks/helpers/repo-context.mjs), which drops the
184	// mount prefix before attributes are ever consulted, so that exclusion holds on a host
185	// and a checkout that honor no attributes at all. git wants '/' separators in a
186	// pattern; SHARED_SUBDIR is joined with the platform's.
187	export const MOUNT_VENDORED_ATTR = `${SHARED_SUBDIR.split(sep).join('/')}/** linguist-vendored`;
188	
189	export function ensureMountVendoredAttribute(root) {
190	  return ensureAttributeLine(root, MOUNT_VENDORED_ATTR);
191	}
192	
193	function ensureAttributeLine(root, line) {
194	  const path = join(root, '.gitattributes');
195	  const text = existsSync(path) ? readFileSync(path, 'utf8') : '';
196	  if (text.split('\n').some((l) => l.trim() === line)) return false;
197	  writeFileSync(path, (text && !text.endsWith('\n') ? `${text}\n` : text) + `${line}\n`);
198	  return true;
199	}
200	
201	// --- the repo's own local pack, seeded once at adoption ----------------------
202	
203	// Every repo has lessons that are its own and portable nowhere: they need a home the
204	// moment there is anything to write, and a session that has to invent one first
205	// usually doesn't — it writes the rule into `basics` or into a `CLAUDE.md` paragraph
206	// instead, which is how a project's rules end up somewhere the corpus cannot reach.
207	// So adoption seeds the home empty, named for the repo, declared and imported like any
208	// other pack.
209	//
210	// BOOTSTRAP ONLY, and gated like the badge row for the same reason: this is a one-time
211	// seed of a file the repo then OWNS. A nightly that re-created it would resurrect a
212	// pack the owner deliberately deleted, and a nightly that rewrote it would overwrite
213	// the rules it exists to hold.
214	
215	// A repo name as a pack id: kebab-case, the canon's naming rule for a pack directory
216	// (lowercase words joined by single hyphens), since the id is what the declaration,
217	// the mount path and every cross-reference then spell.
218	export const packIdForRepo = (fullName) => (fullName ?? '').split('/').pop()
219	  .replace(/([a-z0-9])([A-Z])/g, '$1-$2')
220	  .replace(/[^a-zA-Z0-9]+/g, '-')
221	  .toLowerCase()
222	  .replace(/^-+|-+$/g, '');
223	
224	const SEED_MANIFEST = (id) => `// ${id} — this repo's own pack: everything local, and portable nowhere. Its rules,
225	// and the checks, skills and tasks that carry them, all live here.
226	// Seeded empty at adoption; everything in it is this repo's to write. A lesson that
227	// would hold in another repo belongs in a canon pack instead — propose it upstream.
228	//
229	// The id is this directory's name and the prose is the RULES.md beside this file —
230	// both by convention (engine/pack_loader/pack-conventions.mjs), so neither is
231	// declared here.
232	export default {
233	  version: 1,
234	  ruleRoutingGuidance: {
235	    belongs: 'everything specific to this repository and portable nowhere else: its working rules, and the checks, skills and tasks carrying them',
236	    excludes: 'anything true beyond this repo — that belongs in a canon pack, proposed upstream',
237	  },
238	  detect: null,
239	  marker: null,
240	  worldRules: [],
241	};
242	`;
243	
244	const SEED_PROSE = (id) => `# ${id} — this repo's own pack
245	
246	The home for everything **specific to this repository**: the rules below, and beside them the
247	checks, skills and tasks that carry them. Nothing local needs a home invented for it — this is
248	that home. This file is loaded into every session through the rules index, so what lands *here*
249	should be a directive an agent can act on, not a description of how something works; a rule a
250	deterministic check can enforce belongs in this pack's \`declared-checks.json\` instead, and a
251	procedure with a nameable trigger in its own \`skills/<name>/SKILL.md\`.
252	
253	A lesson that would hold in another repo does not belong here — propose it to the Claudinite
254	canon instead, where every repo gets it.
255	
256	<!-- Nothing yet. The growth lifecycle writes here; so may you. -->
257	`;
258	
259	const SEED_VERSIONS = (id) => `# ${id} — change record
260	
261	Every change automatic work makes to this pack, newest first: a prose rule added or removed, a
262	check created, a rule corrected against a probe or deleted as irrelevant. The row is written in
263	the same PR as the change it describes, so this file diffs beside it.
264	
265	A run that changed nothing writes no row — this is the log of what happened to the pack, never a
266	log of runs.
267	
268	| Date | Task | Change |
269	|---|---|---|
270	`;
271	
272	// Seed `.claudinite/local/packs/<repo>/` and declare it. Returns the pack id when it
273	// created one, null when the repo already has that pack or already declares any local
274	// pack — a repo that has grown its own home must never get a second, empty one.
275	export function seedRepoLocalPack(root, fullName) {
276	  const id = packIdForRepo(fullName);
277	  if (!id) return null;
278	  const dir = join(root, LOCAL_PACKS_SUBDIR, id);
279	  if (existsSync(dir)) return null;
280	
281	  const settingsFile = settingsPath(root);
282	  let raw;
283	  try { raw = JSON.parse(readFileSync(settingsFile, 'utf8')); } catch { return null; }
284	  const declared = Array.isArray(raw.packs) ? raw.packs : [];
285	  // Any local declaration at all means this repo already has a home of its own.
286	  if (declared.some((p) => String(typeof p === 'string' ? p : p?.id).startsWith('local'))) return null;
287	
288	  mkdirSync(dir, { recursive: true });
289	  writeFileSync(join(dir, 'pack.mjs'), SEED_MANIFEST(id));
290	  writeFileSync(join(dir, 'RULES.md'), SEED_PROSE(id));
291	  writeFileSync(join(dir, 'VERSIONS.md'), SEED_VERSIONS(id));
292	
293	  // Declared as text, never a JSON round-trip: re-serializing rewrites what it was not
294	  // asked to — `ensure_ascii` escapes every non-ASCII character in a settings file full
295	  // of prose, and indent and key order become the serializer's opinion.
296	  const text = readFileSync(settingsFile, 'utf8');
297	  const entry = `"${LOCAL_DECL_PREFIX}${id}"`;
298	  const patched = text.replace(/("packs"\s*:\s*\[)/, (m) => `${m}\n    ${entry},`);
299	  writeFileSync(settingsFile, patched === text
300	    ? text // no `packs` array to extend — leave the file alone rather than guess at its shape
301	    : patched);
302	  return id;
303	}
304	
305	// Strip the retired `badges` setting from the settings file. `badges` is
306	// not in CONFIG_KEYS, so a member still carrying it gets an unknown-setting error
307	// until the key goes; doing it here — beside the retired corpus import, for the
308	// same reason — means the converge that already runs on every member clears it,
309	// and nobody hand-edits a settings file to satisfy a check.
310	// Returns true when the key was removed. A malformed settings file is left alone.
311	//
312	// Cut out as TEXT, re-serializing only as a fallback: a JSON round-trip rewrites
313	// the whole file — re-escaping every non-ASCII character in the prose a settings
314	// file is full of — so a three-line deletion arrives as a diff touching every
315	// `reason` in the repo.
316	export function removeRetiredBadgeSetting(root) {
317	  const path = settingsPath(root);
318	  if (!existsSync(path)) return false;
319	  const text = readFileSync(path, 'utf8');
320	  let raw;
321	  try { raw = JSON.parse(text); } catch { return false; }
322	  if (raw === null || typeof raw !== 'object' || Array.isArray(raw) || raw.badges === undefined) return false;
323	  // The key as a materialized settings file carries it: two-space indent, either
324	  // followed by a comma (mid-object) or preceded by one (last key).
325	  const surgical = text.replace(/(,)?\n[ \t]*"badges"[ \t]*:[ \t]*\{[^{}]*\}(,)?(?=\n)/, (m, before, after) => (before && after ? ',' : ''));
326	  const next = surgical !== text && parses(surgical, raw) ? surgical
327	    : JSON.stringify(rest(raw), null, 2) + '\n';
328	  writeFileSync(path, next);
329	  return true;
330	}
331	
332	const rest = ({ badges, ...keep }) => keep;
333	// The surgical cut is only taken when it produces the settings the round-trip would
334	// have — never trust a regex against JSON without re-reading what it made.
335	const parses = (text, raw) => {
336	  try { return JSON.stringify(JSON.parse(text)) === JSON.stringify(rest(raw)); }
337	  catch { return false; }
338	};
339	
340	// The row's entries: each declared pack (the `requires` closure included, in
341	// declaration order) that has a badge on disk, as { id, path } with the path
342	// relative to the repo root. Derived from the pack's own `dir`, so it resolves to
343	// `packs/<id>/…` in the canon home and `.claudinite/shared/packs/<id>/…` in a
344	// consumer with no branch on which repo this is. A pack whose badge is missing is
345	// skipped rather than reported: a repo's own local pack need not have one.
346	export async function badgeRowEntries(root, config) {
347	  const { loadPacks, resolveDeclaredPacks, packEntryId } = await import('./pack_loader/pack-registry.mjs');
348	  const packs = await loadPacks({ localRoot: root });
349	  const byId = new Map(packs.map((p) => [p.id, p]));
350	  const entries = [];
351	  for (const entry of resolveDeclaredPacks(config.packs ?? [], packs)) {
352	    const pack = byId.get(packEntryId(entry));
353	    if (!pack || typeof pack.badge !== 'string' || !pack.badge) continue;
354	    const path = relative(root, join(pack.dir, pack.badge)).split('\\').join('/');
355	    if (existsSync(join(root, path))) entries.push({ id: pack.id, path });
356	  }
357	  return entries;
358	}
359	
360	export const renderBadgeRow = (entries) =>
361	  `${BADGE_ROW_START}\n${entries.map((e) => `![${e.id}](${e.path} "${e.id}")`).join(' ')}${BADGE_ROW_END}`;
362	
363	// Write the row into the repo's README: replacing the delimited block where one
364	// exists, otherwise introducing it just under the title (a README's badges belong
365	// where a reader looks first) or at the very top when there is no heading.
366	// Returns true when the file was written. No README, or nothing to show, means
367	// nothing to do — this converge never creates a README.
368	export function convergeBadgeRow(root, entries) {
369	  const path = join(root, README);
370	  if (!existsSync(path) || !entries.length) return false;
371	  const text = readFileSync(path, 'utf8');
372	  const row = renderBadgeRow(entries);
373	  if (BADGE_ROW_RE.test(text)) {
374	    const next = text.replace(BADGE_ROW_RE, row);
375	    if (next === text) return false;
376	    writeFileSync(path, next);
377	    return true;
378	  }
379	  const lines = text.split('\n');
380	  const title = lines.findIndex((l) => l.startsWith('# '));
381	  const at = title === -1 ? 0 : title + 1;
382	  lines.splice(at, 0, ...(at === 0 ? [row, ''] : ['', row]));
383	  writeFileSync(path, lines.join('\n'));
384	  return true;
385	}
386	
387	// Converge every wiring surface, returning a flat summary of what changed (empty
388	// when the repo was already converged). `stubText` is the vendored scheduler stub.
389	//
390	// `badges` defaults off, and that default is the point: the nightly takes this
391	// call as it stands and only bootstrap opts the README row in.
392	// `workflows: false` converges everything EXCEPT `.github/workflows/`. The engine
393	// update flow passes it: the scheduler workflow's content is a function of the
394	// task set, so pack changes are what rewrite it, and only the pack flow carries a
395	// credential that can land a workflow file at all (DESIGN §2.4, §3.7). A flow that
396	// wrote one it cannot deliver would fail its whole push, not just that file.
397	// `seedLocalPack` defaults off for the same reason `badges` does: both are one-time
398	// seeds of files the repo then owns, and only bootstrap passes them.
399	export async function convergeWiring(root, fullName, { badges = false, seedLocalPack = false } = {}) {
400	  const changed = [];
401	  const hooks = ensureHooks(root);
402	  for (const h of hooks.added) changed.push(`hook:${h}`);
403	  if (removeRetiredCorpusImport(root)) changed.push(`removed retired ${CLAUDE_MD} corpus import`);
404	  if (removeRetiredBadgeSetting(root)) changed.push('removed retired badges setting');
405	  // Adoption only, and BEFORE the index: seeding declares a pack, and the index is a
406	  // function of the declaration, so seeding after it would leave the repo's own pack
407	  // unimported until some later converge.
408	  if (seedLocalPack) {
409	    const seeded = seedRepoLocalPack(root, fullName);
410	    if (seeded) changed.push(`seeded ${LOCAL_PACKS_SUBDIR}/${seeded}`);
411	  }
412	  // The CLAUDE.md channel, in dependency order: the index, then the import that
413	  // loads it, then the merge attribute that keeps it from being hand-resolved.
414	  if (await writeRulesIndex(root)) changed.push(RULES_INDEX_FILE);
415	  if (ensureRulesIndexImport(root)) changed.push(`${CLAUDE_MD} rules-index import`);
416	  if (ensureRulesIndexMergeAttribute(root)) changed.push('.gitattributes merge=ours for the rules index');
417	  if (ensureMountVendoredAttribute(root)) changed.push('.gitattributes linguist-vendored for the shared mount');
418	  if (badges && convergeBadgeRow(root, await badgeRowEntries(root, await repoConfig(root)))) changed.push(`${README} pack row`);
419	  return { changed, ...(hooks.error ? { error: hooks.error } : {}) };
420	}
421	
422	// CLI: `node converge-wiring.mjs [owner/repo] [--badges] [--seed-local-pack]` —
423	// converge THIS repo's distribution wiring. The full name comes from argv or
424	// GITHUB_REPOSITORY/CLAUDINITE_REPO. This is the single surface bootstrap (Part 5) and
425	// the update flows both invoke, so the wiring set is defined once, here — and the two
426	// flags are the whole difference between them. Both are ONE-TIME SEEDS of files the repo
427	// then owns (the README badge row, the repo's own local pack), which is exactly why the
428	// nightly must not pass them: it would rewrite a row the owner moved, or resurrect a
429	// pack they deleted. The two workflow files are the tasks pack's to scaffold, and its
430	// own converge-workflows.mjs is the command that does it.
431	async function main() {
432	  const argv = process.argv.slice(2);
433	  const badges = argv.includes('--badges');
434	  const seedLocalPack = argv.includes('--seed-local-pack');
435	  const fullName = argv.find((a) => !a.startsWith('--')) || process.env.GITHUB_REPOSITORY || process.env.CLAUDINITE_REPO;
436	  if (!fullName) { console.error('converge-wiring: need owner/repo (argv or GITHUB_REPOSITORY)'); process.exit(1); }
437	  const root = process.env.CLAUDINITE_REPO_ROOT || process.cwd();
438	  const { changed, error } = await convergeWiring(root, fullName, { badges, seedLocalPack });
439	  if (error) console.log(`! ${error}`);
440	  console.log(changed.length ? `converge-wiring: ${changed.join(', ')}` : 'converge-wiring: already converged');
441	}
442	
443	if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) main();
444

file.content:
// Fresh-path wiring convergence (task-code-work DESIGN §7, the primitive absorbed from
// #405). The deterministic half of the self-refresh that has nothing to do with the
// vendored mount's CONTENT: the repo-specific wiring EVERY Claudinite member carries,
// converged idempotently in code so the nightly refresh never needs a model to re-enact
// bootstrap's prose.
//
// DISTRIBUTION WIRING ONLY. What a member needs in order to receive and load pack
// content — the settings hooks, the rules index and the CLAUDE.md import that loads it,
// the .gitattributes entries, the badge row, the repo's own local pack. Scheduling
// wiring is not here: the two workflow files belong to the mechanism that runs them and
// are scaffolded at adoption by the tasks pack (#1317), so a member without that pack
// converges exactly this and nothing about a queue it does not have.
//
// One source of truth: bootstrap Part 5 describes this same set for a fresh adoption;
// this module is what both bootstrap and the update flows CALL, so the wiring can never
// drift between "how a repo is set up" and "how the nightly keeps it set up".
//
// Operates on a repo working tree at `root` with node:fs directly (like
// apply-vendor-set.mjs), returning a summary of what it changed — idempotent: a
// repo already converged produces an empty change list.

import { existsSync, readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { join, dirname, relative, sep } from 'node:path';
import { pathToFileURL } from 'node:url';
import { writeRulesIndex, RULES_INDEX_FILE, RULES_INDEX_IMPORT } from './pack_loader/generate-rules-index.mjs';
import { LOCAL_PACKS_SUBDIR, LOCAL_DECL_PREFIX, SHARED_SUBDIR } from './pack_loader/pack-registry.mjs';
import { settingsPath } from './settings-file.mjs';
import { ENDPOINTS_KEY, LEGACY_ENDPOINTS_KEY } from './checks/helpers/repo-context.mjs';

// The settings-hook registrations a scheduled repo carries (bootstrap Part 5).
// Ensured present without clobbering — a set-union keyed on the command string, so
// a repo's own extra hooks and any hand-added entries survive untouched.
export const REQUIRED_HOOKS = [
  { event: 'SessionStart', matcher: null, command: 'bash $CLAUDE_PROJECT_DIR/.claudinite/shared/engine/hooks/session-start-command.sh' },
  { event: 'Stop', matcher: null, command: 'node $CLAUDE_PROJECT_DIR/.claudinite/shared/engine/hooks/stop-command.mjs' },
  { event: 'PreToolUse', matcher: 'Bash', command: 'node $CLAUDE_PROJECT_DIR/.claudinite/shared/engine/hooks/pretooluse-command.mjs' },
  { event: 'SessionEnd', matcher: null, command: 'node $CLAUDE_PROJECT_DIR/.claudinite/shared/engine/hooks/session-end-command.mjs' },
];

export const SETTINGS_PATH = '.claude/settings.json';
export const CLAUDE_MD = 'CLAUDE.md';
export const README = 'README.md';

// The pack-badge row: the marks of the packs this repo declares, on a single
// line of its README. Adoption seeds it and the repo owns it from there — which
// is why the row is gated behind `{ badges: true }` (the CLI's `--badges`, passed
// by bootstrap alone) rather than converged like the surfaces around it. A
// README belongs to its repo: a nightly that re-derived this row would rewrite a
// member's README every time its declaration moved, so the nightly stays out and
// a stale row is the repo's to fix (re-run the converge with `--badges`).
//
// Delimited by HTML comments rather than located by position, so the row can be
// re-converged in place wherever the repo has moved it, and so anything the repo
// writes AFTER the closing marker on the same line (a tagline, a build badge) is
// its own and survives untouched — which is why the CLOSING marker stays inline,
// at the end of the badges' own line.
//
// The OPENING marker gets a line to itself, and that newline is load-bearing: a
// line that BEGINS with `<!--` opens a CommonMark HTML block, and every character
// through the line carrying `-->` is then emitted as raw HTML. Put the badges
// after the opening marker on one line and a README renders the literal text
// `![basics](…)` instead of the images (#587). Breaking the line ends the HTML
// block at the marker, so the badges start a paragraph and parse as markdown.
export const BADGE_ROW_START = '<!-- claudinite:packs -->';
export const BADGE_ROW_END = '<!-- /claudinite:packs -->';
const BADGE_ROW_RE = new RegExp(`${BADGE_ROW_START}[\\s\\S]*?${BADGE_ROW_END}`);

// The retired corpus-index import (#385): a line importing `.claudinite/shared/CLAUDE.md`.
// The whole line (and its trailing newline) is removed wherever it appears.
const CORPUS_IMPORT_RE = /^.*@\.claudinite\/shared\/CLAUDE\.md.*\n?/m;

// The project's settings, loaded through the one reader that validates them.
// Dynamic and in one place: the scheduler reaches the checks helpers exactly here,
// so the cross-tree import stays a single, reviewable edge.
const repoConfig = async (root) => (await import('./checks/helpers/repo-context.mjs')).loadConfig(root);

// Re-converge the scheduler workflow to the vendored stub, with the cron minute set
// to this repo's stable hashed value (never guessed — hash-minute.mjs, a pure
// function of the full name, so re-vendors and this convergence agree) and the
// `stubText` is the vendored stub's content (the caller reads it from the mount).
// Returns true when the file was written (absent, or drifted from the target).
// What this repo's scheduler workflow SHOULD contain — the stub with its cron
// resolved, as text, touching no disk.
//
// A workflow is now a pure function of its stub. Secrets used to be stamped in here
// by name, which made these files a function of the TASK SET and is what wedged a
// member in #1296. They are stamped by the tasks pack's converge-workflows.mjs, at
// the `# claudinite:secrets` marker in its executor stub (#1336).
//
// Split out from the converge below because the pack update flow needs the answer
// without the side effect: it cannot write this file (its caller pushes with the
// Action's GITHUB_TOKEN, which GitHub never lets near `.github/workflows/`), so it
// WITHHOLDS the content and hands it to a lane that can. A flow that had to write
// the file in order to learn what it should say could not do that.
// Ensure the required settings hooks are present (add-if-missing, never clobber).
// Returns { added: [labels], error? }. A malformed settings file is reported, never
// overwritten (the transactional stance — surface it, don't destroy hand config).
export function ensureHooks(root) {
  const path = join(root, SETTINGS_PATH);
  let settings = {};
  if (existsSync(path)) {
    try { settings = JSON.parse(readFileSync(path, 'utf8')); }
    catch { return { added: [], error: `${SETTINGS_PATH} is not valid JSON — left untouched` }; }
  }
  settings.hooks ??= {};
  const added = [];
  for (const h of REQUIRED_HOOKS) {
    const list = (settings.hooks[h.event] ??= []);
    const present = list.some((group) =>
      (h.matcher == null || group.matcher === h.matcher)
      && (group.hooks ?? []).some((entry) => entry?.command === h.command));
    if (!present) {
      list.push({ ...(h.matcher != null ? { matcher: h.matcher } : {}), hooks: [{ type: 'command', command: h.command }] });
      added.push(`${h.event}${h.matcher ? `[${h.matcher}]` : ''}`);
    }
  }
  if (added.length) {
    mkdirSync(dirname(path), { recursive: true });
    writeFileSync(path, JSON.stringify(settings, null, 2) + '\n');
  }
  return { added };
}

// Remove the retired `@.claudinite/shared/CLAUDE.md` corpus-index import (#385) from
// the repo's CLAUDE.md. Returns true when a line was removed.
export function removeRetiredCorpusImport(root) {
  const path = join(root, CLAUDE_MD);
  if (!existsSync(path)) return false;
  const text = readFileSync(path, 'utf8');
  if (!CORPUS_IMPORT_RE.test(text)) return false;
  writeFileSync(path, text.replace(CORPUS_IMPORT_RE, ''));
  return true;
}

// The CLAUDE.md channel (#807): the generated rules index, plus the one line in the
// repo's own CLAUDE.md that imports it. Converged here rather than left to a session
// because the index is a function of the DECLARATION — so the two flows that already
// change a declaration (the nightly engine refresh and any pack change) are exactly
// the moments it can go stale, and both call convergeWiring.
//
// NOT the retired `@.claudinite/shared/CLAUDE.md` this file still strips above. That
// import reached INTO the mount, which is one-directional and slated to become a
// submodule; this one names a consumer-owned file sitting BESIDE it, derived from the
// consumer's own declaration. The two coexist deliberately: a member converging today
// loses the old shape and gains the new one in the same pass.
//
// The import goes after the first `# ` heading when the repo has one (the badge row's
// placement rule, for the same reason — a repo's title stays its first line), and at
// the very top otherwise. A repo with no CLAUDE.md at all gets one: without it the
// index is a file nothing loads.
const RULES_INDEX_IMPORT_RE = new RegExp(`^\\s*${RULES_INDEX_IMPORT.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}\\s*$`, 'm');

export function ensureRulesIndexImport(root) {
  const path = join(root, CLAUDE_MD);
  if (!existsSync(path)) {
    writeFileSync(path, `${RULES_INDEX_IMPORT}\n`);
    return true;
  }
  const text = readFileSync(path, 'utf8');
  if (RULES_INDEX_IMPORT_RE.test(text)) return false;
  const lines = text.split('\n');
  const title = lines.findIndex((l) => l.startsWith('# '));
  const at = title === -1 ? 0 : title + 1;
  lines.splice(at, 0, ...(at === 0 ? [RULES_INDEX_IMPORT, ''] : ['', RULES_INDEX_IMPORT]));
  writeFileSync(path, lines.join('\n'));
  return true;
}

// A GENERATED file wants a `merge=ours` .gitattributes entry (the canon's
// GENERATED-file discipline and the `generated-merge-driver` check that enforces it),
// declared in the same converge that first writes the file — otherwise every member
// picks up an advisory finding on a file it did not author.
export const RULES_INDEX_MERGE_ATTR = 'claudinite-rules.GENERATED.md merge=ours';

export function ensureRulesIndexMergeAttribute(root) {
  return ensureAttributeLine(root, RULES_INDEX_MERGE_ATTR);
}

// The shared mount is canon-owned content the member never authored, so the git HOST
// is told so: Linguist keeps a member's language stats off the corpus (which outweighs
// a small member's own source by byte count) and collapses the mount in a converge
// diff. Presentation only — the CHECK-scope exclusion is a separate, structural rule
// in the file-set builder (engine/checks/helpers/repo-context.mjs), which drops the
// mount prefix before attributes are ever consulted, so that exclusion holds on a host
// and a checkout that honor no attributes at all. git wants '/' separators in a
// pattern; SHARED_SUBDIR is joined with the platform's.
export const MOUNT_VENDORED_ATTR = `${SHARED_SUBDIR.split(sep).join('/')}/** linguist-vendored`;

export function ensureMountVendoredAttribute(root) {
  return ensureAttributeLine(root, MOUNT_VENDORED_ATTR);
}

function ensureAttributeLine(root, line) {
  const path = join(root, '.gitattributes');
  const text = existsSync(path) ? readFileSync(path, 'utf8') : '';
  if (text.split('\n').some((l) => l.trim() === line)) return false;
  writeFileSync(path, (text && !text.endsWith('\n') ? `${text}\n` : text) + `${line}\n`);
  return true;
}

// --- the repo's own local pack, seeded once at adoption ----------------------

// Every repo has lessons that are its own and portable nowhere: they need a home the
// moment there is anything to write, and a session that has to invent one first
// usually doesn't — it writes the rule into `basics` or into a `CLAUDE.md` paragraph
// instead, which is how a project's rules end up somewhere the corpus cannot reach.
// So adoption seeds the home empty, named for the repo, declared and imported like any
// other pack.
//
// BOOTSTRAP ONLY, and gated like the badge row for the same reason: this is a one-time
// seed of a file the repo then OWNS. A nightly that re-created it would resurrect a
// pack the owner deliberately deleted, and a nightly that rewrote it would overwrite
// the rules it exists to hold.

// A repo name as a pack id: kebab-case, the canon's naming rule for a pack directory
// (lowercase words joined by single hyphens), since the id is what the declaration,
// the mount path and every cross-reference then spell.
export const packIdForRepo = (fullName) => (fullName ?? '').split('/').pop()
  .replace(/([a-z0-9])([A-Z])/g, '$1-$2')
  .replace(/[^a-zA-Z0-9]+/g, '-')
  .toLowerCase()
  .replace(/^-+|-+$/g, '');

const SEED_MANIFEST = (id) => `// ${id} — this repo's own pack: everything local, and portable nowhere. Its rules,
// and the checks, skills and tasks that carry them, all live here.
// Seeded empty at adoption; everything in it is this repo's to write. A lesson that
// would hold in another repo belongs in a canon pack instead — propose it upstream.
//
// The id is this directory's name and the prose is the RULES.md beside this file —
// both by convention (engine/pack_loader/pack-conventions.mjs), so neither is
// declared here.
export default {
  version: 1,
  ruleRoutingGuidance: {
    belongs: 'everything specific to this repository and portable nowhere else: its working rules, and the checks, skills and tasks carrying them',
    excludes: 'anything true beyond this repo — that belongs in a canon pack, proposed upstream',
  },
  detect: null,
  marker: null,
  worldRules: [],
};
`;

const SEED_PROSE = (id) => `# ${id} — this repo's own pack

The home for everything **specific to this repository**: the rules below, and beside them the
checks, skills and tasks that carry them. Nothing local needs a home invented for it — this is
that home. This file is loaded into every session through the rules index, so what lands *here*
should be a directive an agent can act on, not a description of how something works; a rule a
deterministic check can enforce belongs in this pack's \`declared-checks.json\` instead, and a
procedure with a nameable trigger in its own \`skills/<name>/SKILL.md\`.

A lesson that would hold in another repo does not belong here — propose it to the Claudinite
canon instead, where every repo gets it.

<!-- Nothing yet. The growth lifecycle writes here; so may you. -->
`;

const SEED_VERSIONS = (id) => `# ${id} — change record

Every change automatic work makes to this pack, newest first: a prose rule added or removed, a
check created, a rule corrected against a probe or deleted as irrelevant. The row is written in
the same PR as the change it describes, so this file diffs beside it.

A run that changed nothing writes no row — this is the log of what happened to the pack, never a
log of runs.

| Date | Task | Change |
|---|---|---|
`;

// Seed `.claudinite/local/packs/<repo>/` and declare it. Returns the pack id when it
// created one, null when the repo already has that pack or already declares any local
// pack — a repo that has grown its own home must never get a second, empty one.
export function seedRepoLocalPack(root, fullName) {
  const id = packIdForRepo(fullName);
  if (!id) return null;
  const dir = join(root, LOCAL_PACKS_SUBDIR, id);
  if (existsSync(dir)) return null;

  const settingsFile = settingsPath(root);
  let raw;
  try { raw = JSON.parse(readFileSync(settingsFile, 'utf8')); } catch { return null; }
  const declared = Array.isArray(raw.packs) ? raw.packs : [];
  // Any local declaration at all means this repo already has a home of its own.
  if (declared.some((p) => String(typeof p === 'string' ? p : p?.id).startsWith('local'))) return null;

  mkdirSync(dir, { recursive: true });
  writeFileSync(join(dir, 'pack.mjs'), SEED_MANIFEST(id));
  writeFileSync(join(dir, 'RULES.md'), SEED_PROSE(id));
  writeFileSync(join(dir, 'VERSIONS.md'), SEED_VERSIONS(id));

  // Declared as text, never a JSON round-trip: re-serializing rewrites what it was not
  // asked to — `ensure_ascii` escapes every non-ASCII character in a settings file full
  // of prose, and indent and key order become the serializer's opinion.
  const text = readFileSync(settingsFile, 'utf8');
  const entry = `"${LOCAL_DECL_PREFIX}${id}"`;
  const patched = text.replace(/("packs"\s*:\s*\[)/, (m) => `${m}\n    ${entry},`);
  writeFileSync(settingsFile, patched === text
    ? text // no `packs` array to extend — leave the file alone rather than guess at its shape
    : patched);
  return id;
}

// Strip the retired `badges` setting from the settings file. `badges` is
// not in CONFIG_KEYS, so a member still carrying it gets an unknown-setting error
// until the key goes; doing it here — beside the retired corpus import, for the
// same reason — means the converge that already runs on every member clears it,
// and nobody hand-edits a settings file to satisfy a check.
// Returns true when the key was removed. A malformed settings file is left alone.
//
// Cut out as TEXT, re-serializing only as a fallback: a JSON round-trip rewrites
// the whole file — re-escaping every non-ASCII character in the prose a settings
// file is full of — so a three-line deletion arrives as a diff touching every
// `reason` in the repo.
export function removeRetiredBadgeSetting(root) {
  const path = settingsPath(root);
  if (!existsSync(path)) return false;
  const text = readFileSync(path, 'utf8');
  let raw;
  try { raw = JSON.parse(text); } catch { return false; }
  if (raw === null || typeof raw !== 'object' || Array.isArray(raw) || raw.badges === undefined) return false;
  // The key as a materialized settings file carries it: two-space indent, either
  // followed by a comma (mid-object) or preceded by one (last key).
  const surgical = text.replace(/(,)?\n[ \t]*"badges"[ \t]*:[ \t]*\{[^{}]*\}(,)?(?=\n)/, (m, before, after) => (before && after ? ',' : ''));
  const next = surgical !== text && parses(surgical, raw) ? surgical
    : JSON.stringify(rest(raw), null, 2) + '\n';
  writeFileSync(path, next);
  return true;
}

const rest = ({ badges, ...keep }) => keep;
// The surgical cut is only taken when it produces the settings the round-trip would
// have — never trust a regex against JSON without re-reading what it made.
const parses = (text, raw) => {
  try { return JSON.stringify(JSON.parse(text)) === JSON.stringify(rest(raw)); }
  catch { return false; }
};

// The row's entries: each declared pack (the `requires` closure included, in
// declaration order) that has a badge on disk, as { id, path } with the path
// relative to the repo root. Derived from the pack's own `dir`, so it resolves to
// `packs/<id>/…` in the canon home and `.claudinite/shared/packs/<id>/…` in a
// consumer with no branch on which repo this is. A pack whose badge is missing is
// skipped rather than reported: a repo's own local pack need not have one.
export async function badgeRowEntries(root, config) {
  const { loadPacks, resolveDeclaredPacks, packEntryId } = await import('./pack_loader/pack-registry.mjs');
  const packs = await loadPacks({ localRoot: root });
  const byId = new Map(packs.map((p) => [p.id, p]));
  const entries = [];
  for (const entry of resolveDeclaredPacks(config.packs ?? [], packs)) {
    const pack = byId.get(packEntryId(entry));
    if (!pack || typeof pack.badge !== 'string' || !pack.badge) continue;
    const path = relative(root, join(pack.dir, pack.badge)).split('\\').join('/');
    if (existsSync(join(root, path))) entries.push({ id: pack.id, path });
  }
  return entries;
}

export const renderBadgeRow = (entries) =>
  `${BADGE_ROW_START}\n${entries.map((e) => `![${e.id}](${e.path} "${e.id}")`).join(' ')}${BADGE_ROW_END}`;

// Write the row into the repo's README: replacing the delimited block where one
// exists, otherwise introducing it just under the title (a README's badges belong
// where a reader looks first) or at the very top when there is no heading.
// Returns true when the file was written. No README, or nothing to show, means
// nothing to do — this converge never creates a README.
export function convergeBadgeRow(root, entries) {
  const path = join(root, README);
  if (!existsSync(path) || !entries.length) return false;
  const text = readFileSync(path, 'utf8');
  const row = renderBadgeRow(entries);
  if (BADGE_ROW_RE.test(text)) {
    const next = text.replace(BADGE_ROW_RE, row);
    if (next === text) return false;
    writeFileSync(path, next);
    return true;
  }
  const lines = text.split('\n');
  const title = lines.findIndex((l) => l.startsWith('# '));
  const at = title === -1 ? 0 : title + 1;
  lines.splice(at, 0, ...(at === 0 ? [row, ''] : ['', row]));
  writeFileSync(path, lines.join('\n'));
  return true;
}

// Converge every wiring surface, returning a flat summary of what changed (empty
// when the repo was already converged). `stubText` is the vendored scheduler stub.
//
// `badges` defaults off, and that default is the point: the nightly takes this
// call as it stands and only bootstrap opts the README row in.
// `workflows: false` converges everything EXCEPT `.github/workflows/`. The engine
// update flow passes it: the scheduler workflow's content is a function of the
// task set, so pack changes are what rewrite it, and only the pack flow carries a
// credential that can land a workflow file at all (DESIGN §2.4, §3.7). A flow that
// wrote one it cannot deliver would fail its whole push, not just that file.
// `seedLocalPack` defaults off for the same reason `badges` does: both are one-time
// seeds of files the repo then owns, and only bootstrap passes them.
export async function convergeWiring(root, fullName, { badges = false, seedLocalPack = false } = {}) {
  const changed = [];
  const hooks = ensureHooks(root);
  for (const h of hooks.added) changed.push(`hook:${h}`);
  if (removeRetiredCorpusImport(root)) changed.push(`removed retired ${CLAUDE_MD} corpus import`);
  if (removeRetiredBadgeSetting(root)) changed.push('removed retired badges setting');
  // Adoption only, and BEFORE the index: seeding declares a pack, and the index is a
  // function of the declaration, so seeding after it would leave the repo's own pack
  // unimported until some later converge.
  if (seedLocalPack) {
    const seeded = seedRepoLocalPack(root, fullName);
    if (seeded) changed.push(`seeded ${LOCAL_PACKS_SUBDIR}/${seeded}`);
  }
  // The CLAUDE.md channel, in dependency order: the index, then the import that
  // loads it, then the merge attribute that keeps it from being hand-resolved.
  if (await writeRulesIndex(root)) changed.push(RULES_INDEX_FILE);
  if (ensureRulesIndexImport(root)) changed.push(`${CLAUDE_MD} rules-index import`);
  if (ensureRulesIndexMergeAttribute(root)) changed.push('.gitattributes merge=ours for the rules index');
  if (ensureMountVendoredAttribute(root)) changed.push('.gitattributes linguist-vendored for the shared mount');
  if (badges && convergeBadgeRow(root, await badgeRowEntries(root, await repoConfig(root)))) changed.push(`${README} pack row`);
  return { changed, ...(hooks.error ? { error: hooks.error } : {}) };
}

// CLI: `node converge-wiring.mjs [owner/repo] [--badges] [--seed-local-pack]` —
// converge THIS repo's distribution wiring. The full name comes from argv or
// GITHUB_REPOSITORY/CLAUDINITE_REPO. This is the single surface bootstrap (Part 5) and
// the update flows both invoke, so the wiring set is defined once, here — and the two
// flags are the whole difference between them. Both are ONE-TIME SEEDS of files the repo
// then owns (the README badge row, the repo's own local pack), which is exactly why the
// nightly must not pass them: it would rewrite a row the owner moved, or resurrect a
// pack they deleted. The two workflow files are the tasks pack's to scaffold, and its
// own converge-workflows.mjs is the command that does it.
async function main() {
  const argv = process.argv.slice(2);
  const badges = argv.includes('--badges');
  const seedLocalPack = argv.includes('--seed-local-pack');
  const fullName = argv.find((a) => !a.startsWith('--')) || process.env.GITHUB_REPOSITORY || process.env.CLAUDINITE_REPO;
  if (!fullName) { console.error('converge-wiring: need owner/repo (argv or GITHUB_REPOSITORY)'); process.exit(1); }
  const root = process.env.CLAUDINITE_REPO_ROOT || process.cwd();
  const { changed, error } = await convergeWiring(root, fullName, { badges, seedLocalPack });
  if (error) console.log(`! ${error}`);
  console.log(changed.length ? `converge-wiring: ${changed.join(', ')}` : 'converge-wiring: already converged');
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) main();

