78	// The record line for this item, or null where the vocabulary has no true answer.
79	export const recordLine = (item, status) => {
80	  const parsed = parseWorkItemTitle(item.title);
81	  return status && parsed
82	    ? renderTaskExec({ pack: parsed.pack, task: parsed.task, slotId: `#${item.number}`, status })
83	    : null;
84	};
