86	// The comment one converge writes: the session's account, then the record, so a
87	// reader and a parser both find what they came for in one place.
88	export function convergeComment(item, { summary, pr, record }) {
89	  const rec = recordLine(item, record);
90	  const line = rec ? `\n\n\`\`\`\n${rec}\n\`\`\`` : '';
91	  const waiting = pr ? `\n\nWaiting on a person: merge or close #${pr}, then close this item.` : '';
92	  return `${summary.trim()}${waiting}${line}`;
